with valid_departments as (select * from departments where dept_name = 'Engineering' and budget between 2441000 and 3761000), summary as (select case when budget >= 4089000 then 'high' when budget >= 1889000 then 'mid' else 'low' end as budget_bucket, case when location in ('London', 'Berlin') then 'group_a' else 'other' end as location_group, sum(case when dept_name = 'Marketing' then 1 else 0 end) as marketing_count from valid_departments group by case when budget >= 4089000 then 'high' when budget >= 1889000 then 'mid' else 'low' end, case when location in ('London', 'Berlin') then 'group_a' else 'other' end) select * from summary order by location_group, marketing_count desc
